AssistantMessageToolRequest(name='create', tool_call_id='function-call-359fe406-3923-4bc1-acc7-e42e5a4b0c1a', arguments={'file_text': 'const { useState, useEffect, useRef } = React;

const Modal = ({ isOpen, onClose, title, children, onConfirm }) => {
    const modalRef = useRef(null);
    const firstFocusableRef = useRef(null);
    const lastFocusableRef = useRef(null);

    useEffect(() => {
        const handleEscape = (e) => {
            if (e.key === 'Escape') onClose();
        };

        if (isOpen) {
            document.addEventListener('keydown', handleEscape);
            document.body.style.overflow = 'hidden';

            // Focus trap logic
            const focusableElements = modalRef.current.querySelectorAll(
                'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
            );
            if (focusableElements.length > 0) {
                firstFocusableRef.current = focusableElements[0];
                lastFocusableRef.current = focusableElements[focusableElements.length - 1];
                firstFocusableRef.current.focus();
            }
        } else {
            document.body.style.overflow = 'unset';
        }

        return () => {
            document.removeEventListener('keydown', handleEscape);
            document.body.style.overflow = 'unset';
        };
    }, [isOpen, onClose]);

    const handleTabKey = (e) => {
        if (e.key !== 'Tab') return;

        if (e.shiftKey) {
            if (document.activeElement === firstFocusableRef.current) {
                e.preventDefault();
                lastFocusableRef.current.focus();
            }
        } else {
            if (document.activeElement === lastFocusableRef.current) {
                e.preventDefault();
                firstFocusableRef.current.focus();
            }
        }
    };

    if (!isOpen) return null;

    return ReactDOM.createPortal(
        <div 
            className={`modal-overlay ${isOpen ? 'open' : ''}`} 
            onClick={onClose}
            onKeyDown={handleTabKey}
        >
            <div 
                className="modal-content" 
                onClick={(e) => e.stopPropagation()}
                role="dialog"
                aria-modal="true"
                aria-labelledby="modal-title"
                aria-describedby="modal-description"
                ref={modalRef}
            >
                <div className="modal-header">
                    <h2 id="modal-title">{title}</h2>
                </div>
                <div className="modal-body" id="modal-description">
                    {children}
                </div>
                <div className="modal-footer">
                    <button className="btn btn-secondary" onClick={onClose}>
                        Cancel
                    </button>
                    <button className="btn btn-danger" onClick={onConfirm}>
                        Delete
                    </button>
                </div>
            </div>
        </div>,
        document.body
    );
};

const App = () => {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const triggerRef = useRef(null);

    const openModal = () => setIsModalOpen(true);
    const closeModal = () => {
        setIsModalOpen(false);
        // Return focus to trigger when closed
        if (triggerRef.current) {
            triggerRef.current.focus();
        }
    };

    const handleDelete = () => {
        console.log("Image deleted");
        closeModal();
    };

    return (
        <div className="preview-container">
            <img 
                src="https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80" 
                alt="Beautiful landscape with mountains and a lake" 
                className="preview-image"
            />
            <div className="actions">
                <button 
                    className="trigger" 
                    onClick={openModal}
                    ref={triggerRef}
                    aria-haspopup="dialog"
                >
                    Delete Image
                </button>
            </div>

            <Modal 
                isOpen={isModalOpen} 
                onClose={closeModal} 
                onConfirm={handleDelete}
                title="Delete Image?"
            >
                <p>Are you sure you want to delete this image? This action cannot be undone.</p>
            </Modal>
        </div>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
