    border-radius: 6px;
    font-weight: 600;
    cursor: pointer;
    border: none;
    transition: background-color 0.2s;
}

.btn-secondary {
    background-color: transparent;
    color: var(--text-color);
    border: 1px solid var(--text-muted);
}

.btn-secondary:hover {
    background-color: rgba(255, 255, 255, 0.05);
